func collectCompositeAccount(rows *orm.Rows, keyFn func(*CompositeAccountRow) orm.Key) *orm.Collection[CompositeAccountRow] {
	c := orm.NewCollection[CompositeAccountRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanCompositeAccount(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectCompositeAccountDirect(rows []*CompositeAccountRow, keyFn func(*CompositeAccountRow) orm.Key) *orm.Collection[CompositeAccountRow] {
	c := orm.NewCollection[CompositeAccountRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.TenantId, r.AccountId}), r)
		}
	}
	return c
}

