func (q *CompositeAccountQuery) Paginate(page, per int) (*orm.Page[CompositeAccountRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	if per <= 0 {
		return nil, &ir.Error{Code: "IR_INVALID", Msg: "per must be positive"}
	}
	if page < 1 {
		page = 1
	}
	q.q.Req.IR.Kind = "paginate"
	q.q.Node.Limit = &ir.Limit{Offset: (page - 1) * per, Count: per}
	rows, total, err := orm.Paginate(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	pages := (total + int64(per) - 1) / int64(per)
	return &orm.Page[CompositeAccountRow]{Items: collectCompositeAccount(rows, q.keyFn), Total: total, Pages: pages, Current: int64(page), Per: int64(per)}, nil
}

